SELECT 
FROM `category`
WHERE is_deleted = 0

    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR slug LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND parent_id = #{parentId}

ORDER BY sort_order ASC, id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM `category`
WHERE is_deleted = 0

    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR slug LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND parent_id = #{parentId}

SELECT FROM `category` WHERE is_deleted = 0
AND status = #{status}
ORDER BY sort_order ASC, id ASC

SELECT COUNT(*) FROM `category`
WHERE slug = #{slug} AND is_deleted = 0

    AND id != #{excludeId}
